		}
	}
	if inputs.PriorityChanged {
		if p := trail.Priority(strings.TrimSpace(inputs.Priority)); !p.IsValid() {
			return fmt.Errorf("invalid priority %q: valid values are %s", inputs.Priority, formatValidPriorities())
		}
