	var force bool
	var worktree bool

	cmd := &cobra.Command{
		Use:   "checkout [<trail>]",
		Short: "Check out a trail's branch",
		Long: `Check out the branch of a trail.

item.formatted_output:
	// Find the trail by branch.
	found, err := findTrailByBranch(ctx, client, forge, owner, repoName, branch)
	if err != nil {
		return err
